use rhwp::DocumentCore;
use rhwp::model::{document::Document,control::Control};
use serde_json::{Value,json};use sha2::{Digest,Sha256};use std::path::PathBuf;
fn sha(b:&[u8])->String{Sha256::digest(b).iter().map(|b|format!("{b:02x}")).collect()}
fn state(d:&DocumentCore)->Value{json!((0..d.page_count()).map(|p|json!({"page":p,"controls":serde_json::from_str::<Value>(&d.get_page_control_layout_native(p).unwrap()).unwrap(),"text":serde_json::from_str::<Value>(&d.get_page_text_layout_native(p).unwrap()).unwrap()})).collect::<Vec<_>>())}
fn safe(v:&Value)->Value{match v{Value::Number(_)|Value::Null|Value::Bool(_)=>v.clone(),Value::String(s)=>json!({"kind":"string","characters":s.chars().count(),"sha256":sha(s.as_bytes())}),_=>json!({"kind":if v.is_array(){"array"}else{"object"},"sha256":sha(&serde_json::to_vec(v).unwrap())})}}
fn diff(a:&Value,b:&Value,p:&str,out:&mut Vec<Value>){match(a,b){(Value::Number(a),Value::Number(b))=>{let(x,y)=(a.as_f64().unwrap(),b.as_f64().unwrap());if !x.is_finite()||!y.is_finite()||(x-y).abs()>0.2{out.push(json!({"path":p,"before":a,"after":b}));}},(Value::Array(a),Value::Array(b))=>{if a.len()!=b.len(){out.push(json!({"path":format!("{p}/length"),"before":a.len(),"after":b.len()}));}for i in 0..a.len().max(b.len()){diff(a.get(i).unwrap_or(&Value::Null),b.get(i).unwrap_or(&Value::Null),&format!("{p}/{i}"),out);}},(Value::Object(a),Value::Object(b))=>{let keys:std::collections::BTreeSet<_>=a.keys().chain(b.keys()).collect();for k in keys{diff(a.get(k).unwrap_or(&Value::Null),b.get(k).unwrap_or(&Value::Null),&format!("{p}/{k}"),out);}},_=>if a!=b{out.push(json!({"path":p,"before":safe(a),"after":safe(b)}));}}}
use rhwp::model::document::HWPX_ORIGIN_STREAM_PATH;use rhwp::parser::FileFormat;
fn input(name:&str)->Vec<u8>{std::fs::read(PathBuf::from(std::env::var("JUEONY_REPO").unwrap()).join(name)).unwrap()}
fn names(bytes:&[u8])->Vec<String>{let c=cfb::CompoundFile::open(std::io::Cursor::new(bytes)).unwrap();c.walk().filter(|e|e.is_stream()).map(|e|e.path().to_string_lossy().into_owned()).collect()}
#[test]fn own_xml_to_hwp_standard_summary_owner_five_fields(){let d=DocumentCore::from_bytes(&input("build/metadata-author-closure82/own-summary-five-fields-source.hwpx")).unwrap();let values:Value=serde_json::from_str(&d.get_document_metadata_native()).unwrap();let before=state(&d);let source=serde_json::to_vec(&d.document().extra_streams).unwrap();let a=d.export_hwp_with_adapter_snapshot_with_report().unwrap();assert!(a.content_loss().is_empty());let ns=names(a.bytes());assert!(ns.contains(&"/\u{5}HwpSummaryInformation".into()));assert!(!ns.contains(&"/HwpSummaryInformation".into()));let r=DocumentCore::from_bytes(a.bytes()).unwrap();let after:Value=serde_json::from_str(&r.get_document_metadata_native()).unwrap();assert_eq!(values["values"],after["values"]);let mut ds=vec![];diff(&before,&state(&r),"pages",&mut ds);assert!(ds.is_empty());assert_eq!(source,serde_json::to_vec(&d.document().extra_streams).unwrap());}
#[test]fn original_native_ascii_stream_is_never_renamed(){let b=input("build/mcst-cross-closure77/mcst-actual-v7-final-native-review.hwp");let d=DocumentCore::from_bytes(&b).unwrap();assert!(names(&b).contains(&"/HwpSummaryInformation".into()));let a=d.export_hwp_with_adapter_snapshot_with_report().unwrap();assert!(names(a.bytes()).contains(&"/HwpSummaryInformation".into()));assert!(!names(a.bytes()).contains(&"/\u{5}HwpSummaryInformation".into()));}
#[test]fn historical_exact_six_accepts_one_summary_spelling_only(){let d=DocumentCore::from_bytes(&input("build/hancom-final-file-review-20261017/mcst-bid-2026-hwpx.hwpx")).unwrap();for mode in["ascii","standard","duplicate-alias","missing","opaque","case-change"]{let mut m=d.document().clone();for(p,_)in &mut m.extra_streams{if p=="/\u{5}HwpSummaryInformation"{*p="/HwpSummaryInformation".into();}}match mode{"standard"=>m.extra_streams.iter_mut().find(|(p,_)|p=="/HwpSummaryInformation").unwrap().0="/\u{5}HwpSummaryInformation".into(),"duplicate-alias"=>m.extra_streams.iter_mut().find(|(p,_)|p=="/PrvText").unwrap().0="/\u{5}HwpSummaryInformation".into(),"missing"=>m.extra_streams.retain(|(p,_)|p!="/Scripts/JScriptVersion"),"opaque"=>m.extra_streams.iter_mut().find(|(p,_)|p=="/PrvText").unwrap().0="/opaque".into(),"case-change"=>m.extra_streams.iter_mut().find(|(p,_)|p=="/HwpSummaryInformation").unwrap().0="/hwpsummaryinformation".into(),_=>{}}let before=m.extra_streams.clone();rhwp::document_core::converters::hwpx_to_hwp::convert_if_hwpx_source(&mut m,FileFormat::Hwpx);assert_eq!(m.extra_streams.iter().any(|(p,_)|p==HWPX_ORIGIN_STREAM_PATH),!matches!(mode,"ascii"|"standard"),"{mode}");for row in before{assert!(m.extra_streams.contains(&row),"rewrote original {mode}");}}}
#[test]fn actual_historical_full_layout_exact(){for p in["build/hancom-final-file-review-20261017/mcst-bid-2026-hwpx-hancom.hwpx","build/hancom-final-file-review-20261017/mcst-bid-2026-hwpx.hwpx"]{let b=input(p);let d=DocumentCore::from_bytes(&b).unwrap();let a=d.export_hwp_with_adapter_snapshot_with_report().unwrap();assert!(a.content_loss().is_empty());let r=DocumentCore::from_bytes(a.bytes()).unwrap();let mut ds=vec![];diff(&state(&d),&state(&r),"pages",&mut ds);assert!(ds.is_empty(),"{p} differences{}",ds.len());assert_eq!(input(p),b);}}
#[test]fn compiled_prefix_source_matches_disk(){let base=PathBuf::from(env!("CARGO_MANIFEST_DIR"));for(rel,b)in[("src/parser/hwpx/contract_streams.rs",include_bytes!("../src/parser/hwpx/contract_streams.rs").as_slice()),("src/document_core/converters/hwpx_to_hwp.rs",include_bytes!("../src/document_core/converters/hwpx_to_hwp.rs").as_slice())]{assert_eq!(b,std::fs::read(base.join(rel)).unwrap());eprintln!("COMPILED_PREFIX_SOURCE {rel} {}",sha(b));}}
